var i=`0679-fakoye`;var a=`world-0679`;var t=`ML`;var s=`western-africa`;var o=4;var r=71;var g={en:`Fakoye`,ua:`Факойє`};var l={en:`Fakoye is a Mali classic prepared with beef chuck, yellow onion, okra, spinach. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Факойє, страва кухні країни Малі зі складниками: яловича лопатка, жовта цибуля, бамія, шпинат. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-chuck`,620,`g`],[`yellow-onion`,150,`g`],[`red-palm-oil`,50,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 55 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 55 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:55,i:[[`okra`,340,`g`],[`spinach`,350,`g`],[`water`,750,`ml`],[`tomato`,250,`g`],[`dawadawa`,12,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`ground-cumin`,5,`g`]]}];var h={slug:i,id:a,country:`ML`,region:s,servings:4,minutes:71,title:g,text:l,steps:d};export{t as country,h as default,a as id,r as minutes,s as region,o as servings,i as slug,d as steps,l as text,g as title};